import { defineConfig, globalIgnores } from 'eslint/config';
import customConfig from 'eslint-config-phun-ky';

export default defineConfig([
  // Generated by tsc, release-it, TypeDoc and VitePress; CLAUDE.md is local
  // and not committed
  globalIgnores([
    'dist/**',
    'coverage/**',
    'CHANGELOG.md',
    'CLAUDE.md',
    'docs/api/**',
    'docs/.vitepress/cache/**',
    'docs/.vitepress/dist/**'
  ]),
  {
    extends: [customConfig],
    rules: {
      // Runs only in Node (see engines), never in a browser
      'compat/compat': 'off',
      // House convention: early returns instead of nested ternaries
      'no-nested-ternary': 'error',
      // The SDK's "./*" export maps types to "<path>.js.d.ts", which the
      // resolver can't find; Node and tsc resolve these imports fine. The
      // docs site's API sidebar is generated by docs:gen, after lint in CI
      'import-x/no-unresolved': [
        'error',
        {
          ignore: [
            '^@modelcontextprotocol/sdk/',
            '^\\.\\./api/typedoc-sidebar\\.json$'
          ]
        }
      ]
    }
  },
  {
    // Command-line scripts report to the terminal
    files: ['scripts/**'],
    rules: { 'no-console': 'off' }
  }
]);
